using namespace std;
class Box {
    double l, w, h;
public:
    Box() {
        l = 1;
        w = 1;
        h = 1;
    }
    Box(double side) {
        l = side;
        w = side;
        h = side;
    }
    Box(double a, double b, double c) {
        l = a;
        w = b;
        h = c;
    }
    double volume() {
