        try {
            c.book(requests[k]);
            cout << "Booked " << requests[k] << " seats" << endl;
        } catch (string msg) {
            cout << "Error: " << msg << endl;
        }
    }
    cout << "Seats Left: " << c.getAvailable() << endl;
    return 0;
}

