        while (i > 0 && h[(i - 1) / 2] > h[i]) {
            int parent = (i - 1) / 2;
            int temp = h[parent];
            h[parent] = h[i];
            h[i] = temp;
            i = parent;
        }
    }
    cout << "Min-Heap:";
    for (int i = 0; i < size; i++) {
        cout << " " << h[i];
    }
