    Node *node = new Node;
    node->data = c;
    node->left = NULL;
    node->right = NULL;
    return node;
}
void printInfix(Node *root) {
    if (root == NULL) {
        return;
    }
    if (root->left == NULL && root->right == NULL) {
        cout << root->data;
        return;
    }
    cout << "(";
    printInfix(root->left);
    cout << root->data;
    printInfix(root->right);
    cout << ")";
}
int main() {
