    Node *stk[55];
    int top = -1;
    cin >> s;
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        Node *node = newNode(c);
        if (c < 'a' || c > 'z') {
            node->right = stk[top];
            top--;
            node->left = stk[top];
            top--;
        }
        top++;
        stk[top] = node;
    }
    cout << "Infix Expression: ";
    printInfix(stk[top]);
    cout << endl;
    return 0;
}

