    if (root == NULL) {
        Node *node = new Node;
        node->data = x;
        node->left = NULL;
        node->right = NULL;
        return node;
    }
    if (x < root->data) {
        root->left = insert(root->left, x);
    } else {
        root->right = insert(root->right, x);
    }
    return root;
}
