    cin >> n;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        root = insert(root, x);
    }
    cin >> key;
    Node *curr = root;
    int depth = 0;
    while (curr != NULL && curr->data != key) {
        if (key < curr->data) {
            curr = curr->left;
        } else {
            curr = curr->right;
        }
        depth++;
    }
    if (curr == NULL) {
        cout << "Not Found" << endl;
    } else {
        cout << "Found at depth " << depth << endl;
    }
    return 0;
}

